arguments.command:
cd /tmp/vally-eval-trial-DcbrZ1; mkdir -p tests/CheckoutPricing.UnitTests/Acceptance
cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
namespace CheckoutPricing.Application;

public enum CustomerTier { Standard, Gold }

public sealed record CalculatePayableTotalQuery(CustomerTier Tier, decimal OrderSubtotal);

public sealed class CalculatePayableTotalHandler
{
    public decimal Handle(CalculatePayableTotalQuery query) => query.OrderSubtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/Acceptance/LoyaltyDiscountAcceptanceTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.Acceptance;

public sealed class LoyaltyDiscountAcceptanceTests
{
    [Fact]
    public void S1_GoldCustomerReceivesTheApprovedDiscount()
    {
        var handler = new CalculatePayableTotalHandler();

        var payableTotal = handler.Handle(new CalculatePayableTotalQuery(CustomerTier.Gold, 100.00m));

        Assert.Equal(95.00m, payableTotal);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests --verbosity quiet 2>&1 | tail -20

